catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    var ga = new GlideAjax('EventDetailsClientUtils');
    ga.addParam('sysparm_name', 'getEventDetails');
    ga.addParam('sysparm_event_id', newValue);

    ga.getXMLAnswer(function(response) {
        var eventInfo = JSON.parse(response);

        if (eventInfo.error) {
            g_form.showFieldMsg('u_event_id', eventInfo.error, 'error');
        } else {
            // Display event details in an alert or populate other fields if needed
            alert(
                "Event Name: " + eventInfo.name +
                "\nDate: " + eventInfo.date +
                "\nLocation: " + eventInfo.location +
                "\nStatus: " + eventInfo.status +
                "\nContact Person: " + eventInfo.contact +
                "\nEmail: " + eventInfo.email
            );
        }
    });
}
